<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta name="theme-color" content="#f4f7f2">
  <title>Stockroom · Inventory</title>
  <style>
    :root{font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:#18251d;background:#f4f7f2;font-synthesis:none;text-rendering:optimizeLegibility}*{box-sizing:border-box}body{margin:0;min-height:100vh}button,input{font:inherit}button{cursor:pointer}.hidden{display:none!important}.app{min-height:100vh}.sidebar{position:fixed;inset:0 auto 0 0;z-index:20;width:250px;padding:26px 18px 18px;background:#fff;border-right:1px solid #e4eae2;display:flex;flex-direction:column;transition:width .2s ease}.brand{display:flex;align-items:center;gap:12px;padding:0 8px 30px;color:#193b28;text-decoration:none}.brand-mark{width:42px;height:42px;border-radius:13px;background:#267746;color:white;display:grid;place-items:center;font-size:21px;font-weight:800}.brand-name{font-size:18px;font-weight:750;letter-spacing:-.03em}.brand-caption{display:block;color:#849187;font-size:11px;margin-top:2px}.nav-caption{padding:0 12px;margin:0 0 10px;color:#95a097;font-size:10px;font-weight:750;letter-spacing:.13em;text-transform:uppercase}.nav{display:grid;gap:5px}.nav-link{height:43px;padding:0 12px;display:flex;align-items:center;gap:12px;border:0;border-radius:10px;background:transparent;color:#5d6b61;text-align:left;font-size:13px;font-weight:620}.nav-link:hover{background:#f5f8f4;color:#245c37}.nav-link.active{background:#eaf4eb;color:#24683b}.nav-icon{width:19px;text-align:center;font-size:17px}.nav-count{margin-left:auto;padding:2px 8px;border-radius:99px;background:#fff1d7;color:#8b5c12;font-size:11px}.sidebar-note{margin-top:auto;padding:14px;border:1px solid #e8eee7;border-radius:12px;background:#f8faf7;color:#738078;font-size:11px;line-height:1.55}.sidebar-note strong{display:block;margin-bottom:4px;color:#44564a;font-size:12px}.collapse{position:absolute;right:-13px;top:83px;width:27px;height:27px;border:1px solid #e3e9e2;border-radius:50%;background:#fff;color:#6b786e;box-shadow:0 2px 6px #17231c12}.app.collapsed .sidebar{width:76px;padding-inline:12px}.app.collapsed .brand{justify-content:center;padding-inline:0}.app.collapsed .brand-copy,.app.collapsed .nav-caption,.app.collapsed .nav-label,.app.collapsed .nav-count,.app.collapsed .sidebar-note{display:none}.app.collapsed .nav-link{justify-content:center;padding:0}.main{min-height:100vh;margin-left:250px;padding:30px clamp(22px,4vw,56px) 42px;transition:margin .2s ease}.app.collapsed .main{margin-left:76px}.topbar{max-width:1320px;margin:0 auto 36px;display:flex;align-items:center;justify-content:space-between;gap:14px}.crumb{font-size:12px;color:#89958b}.crumb strong{color:#384b3e;font-weight:650}.top-actions{display:flex;align-items:center;gap:10px}.user-chip{display:flex;align-items:center;gap:9px;color:#49594e;font-size:12px}.avatar{width:34px;height:34px;border-radius:50%;display:grid;place-items:center;background:#e5f1e5;color:#276a3d;font-weight:750}.mobile-brand,.mobile-menu{display:none}.content{max-width:1320px;margin:0 auto}.page-heading{display:flex;align-items:end;justify-content:space-between;gap:16px;margin-bottom:22px}.eyebrow{margin:0 0 7px;color:#7d8b80;font-size:10px;font-weight:750;letter-spacing:.14em;text-transform:uppercase}.page-heading h1{margin:0;font-size:27px;letter-spacing:-.04em}.subheading{margin:7px 0 0;color:#849087;font-size:13px}.button{min-height:40px;padding:0 15px;border:0;border-radius:9px;background:#287746;color:#fff;font-size:12px;font-weight:700}.button:hover{background:#21663b}.button.secondary{border:1px solid #e0e8df;background:#fff;color:#405247}.button.secondary:hover{background:#f8faf7}.button.danger{border:1px solid #f2ddda;background:#fff8f7;color:#a24437}.panel{border:1px solid #e5ebe4;border-radius:14px;background:#fff;box-shadow:0 5px 18px #1a35210a}.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin-bottom:18px}.stat{padding:18px 19px}.stat-label{color:#79867d;font-size:11px;font-weight:600}.stat-value{display:block;margin-top:13px;color:#203329;font-size:25px;font-weight:750;letter-spacing:-.04em}.stat-foot{margin-top:4px;color:#9aa49c;font-size:10px}.stat-icon{float:right;width:34px;height:34px;display:grid;place-items:center;border-radius:10px;background:#edf5ed;color:#347147;font-size:15px}.two-col{display:grid;grid-template-columns:minmax(0,1.45fr) minmax(260px,.8fr);gap:16px}.panel-head{display:flex;align-items:center;justify-content:space-between;padding:17px 19px;border-bottom:1px solid #edf0ed}.panel-title{margin:0;font-size:13px;font-weight:700}.panel-hint{margin:4px 0 0;color:#8b968d;font-size:11px}.text-link{border:0;background:none;color:#287746;font-size:11px;font-weight:700}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse;text-align:left}th,td{padding:12px 15px;border-bottom:1px solid #eff2ef;white-space:nowrap}th{color:#929d94;font-size:9px;font-weight:750;letter-spacing:.09em;text-transform:uppercase}td{color:#49594d;font-size:11px}.product-name{color:#26392d;font-weight:650}.sku{color:#89958b;font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:10px}.pill{display:inline-flex;padding:4px 8px;border-radius:99px;background:#eef5ef;color:#46704e;font-size:9px;font-weight:650}.status{display:inline-flex;padding:4px 8px;border-radius:99px;font-size:9px;font-weight:700}.status.good{background:#edf6ed;color:#347247}.status.low{background:#fff4df;color:#95630b}.status.out{background:#fff0ee;color:#a24336}.empty{padding:34px 18px;text-align:center;color:#929d94;font-size:12px}.form-panel{padding:18px 19px;margin-bottom:16px}.form-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.field label{display:block;margin-bottom:6px;color:#647168;font-size:10px;font-weight:650}.field input{width:100%;height:39px;padding:0 11px;border:1px solid #dfe7df;border-radius:8px;background:#fff;color:#24372b;font-size:12px;outline:none}.field input:focus{border-color:#579168;box-shadow:0 0 0 3px #e6f2e7}.form-actions{display:flex;justify-content:flex-end;margin-top:13px}.search{height:37px;width:min(250px,45vw);padding:0 12px;border:1px solid #e2e9e1;border-radius:8px;outline:none;font-size:11px}.notice{min-height:18px;margin:9px 0 0;color:#a34437;font-size:11px}.auth-wrap{min-height:100vh;display:grid;place-items:center;padding:24px}.auth-card{width:min(440px,100%);padding:32px;border:1px solid #e3e9e2;border-radius:16px;background:#fff;box-shadow:0 12px 36px #213d2610}.auth-card h1{margin:0;font-size:27px;letter-spacing:-.04em}.auth-card>p{color:#849087;font-size:13px}.auth-card form{display:grid;gap:13px;margin-top:24px}.auth-card .field label{font-size:12px}.auth-card .field input{height:45px;font-size:14px}.auth-actions{display:flex;gap:8px;margin-top:4px}.auth-actions .button{height:42px}.auth-message{min-height:17px;color:#ae4637;font-size:12px}.mobile-overlay{display:none}
    @media(max-width:1050px){.stats{grid-template-columns:repeat(2,minmax(0,1fr))}.two-col{grid-template-columns:1fr}.main{padding-inline:25px}}
    @media(max-width:700px){.sidebar{width:260px;transform:translateX(-100%);transition:transform .2s ease}.app.mobile-open .sidebar{transform:translateX(0)}.app.collapsed .sidebar{width:260px;padding:26px 18px 18px}.app.collapsed .brand-copy,.app.collapsed .nav-caption,.app.collapsed .nav-label,.app.collapsed .nav-count,.app.collapsed .sidebar-note{display:initial}.app.collapsed .brand{justify-content:flex-start;padding:0 8px 30px}.app.collapsed .nav-link{justify-content:flex-start;padding:0 12px}.collapse{display:none}.main,.app.collapsed .main{margin-left:0;padding:18px 16px 30px}.mobile-brand,.mobile-menu{display:flex}.mobile-brand{align-items:center;gap:9px;color:#244431;font-size:14px;font-weight:750}.mobile-brand .brand-mark{width:33px;height:33px;border-radius:10px;font-size:16px}.mobile-menu{width:36px;height:36px;align-items:center;justify-content:center;border:1px solid #e2e9e1;border-radius:9px;background:#fff;color:#536258}.topbar{margin-bottom:27px}.crumb,.user-chip span:last-child{display:none}.page-heading{align-items:flex-start}.page-heading h1{font-size:23px}.stats{gap:9px}.stat{padding:14px}.stat-value{font-size:21px}.stat-icon{width:29px;height:29px}.form-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.mobile-overlay{position:fixed;inset:0;z-index:15;background:#17251d66}.app.mobile-open .mobile-overlay{display:block}}
    @media(max-width:420px){.stats{grid-template-columns:1fr 1fr}.form-grid{grid-template-columns:1fr}.auth-card{padding:25px}.page-heading{flex-direction:column;align-items:stretch}.page-heading>.button{align-self:flex-start}}
  </style>
  <style>
    .sidebar{background:linear-gradient(165deg,#fff 0%,#fbfdf9 68%,#f2f8ee 100%)}
    .nav-link{position:relative;overflow:hidden;transform:translateX(0) scale(1);transition:transform .22s cubic-bezier(.2,.8,.2,1),background .22s ease,color .22s ease,box-shadow .22s ease}
    .nav-link:hover,.nav-link:focus-visible{z-index:1;transform:translateX(5px) scale(1.035);background:linear-gradient(105deg,#e4f4e8,#f1f7dc);color:#215f36;box-shadow:0 5px 14px #337b3a18;outline:none}
    .nav-link:hover .nav-icon,.nav-link:focus-visible .nav-icon{transform:scale(1.12) rotate(-4deg)}
    .nav-link .nav-icon{transition:transform .22s cubic-bezier(.2,.8,.2,1)}
    .nav-link.active{background:linear-gradient(110deg,#267746 0%,#42964a 58%,#75ad3b 100%);color:#fff;box-shadow:0 6px 15px #2e7d3d35}
    .nav-link.active .nav-count{background:#ffffff35;color:#fff}
    .nav-link:active{transform:translateX(3px) scale(.99)}
    .avatar img{width:100%;height:100%;border-radius:inherit;object-fit:cover}
    .settings-layout{display:grid;grid-template-columns:190px minmax(0,1fr);gap:16px;max-width:900px}
    .settings-menu{padding:9px;align-self:start}
    .settings-tab{display:flex;width:100%;align-items:center;gap:9px;padding:11px 10px;border:0;border-radius:8px;background:transparent;color:#607066;text-align:left;font-size:11px;font-weight:650;transition:background .18s ease,color .18s ease,transform .18s ease}
    .settings-tab:hover{transform:translateX(3px);background:#f0f7ed;color:#286e3c}
    .settings-tab.active{background:linear-gradient(110deg,#e4f2e7,#f3f8e4);color:#25683a}
    .settings-body{padding:20px}
    .photo-preview{width:88px;height:88px;border-radius:50%;font-size:28px}
    .account-actions{display:flex;align-items:center;justify-content:space-between;gap:12px;max-width:900px;margin-top:16px;padding:17px 20px}
    .button.signout{border:1px solid #f0d9d6;background:#fff7f6;color:#a14439}
    .button.signout:hover{background:#ffedeb}
    .analytics-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin-bottom:16px}
    .chart-panel{min-width:0;overflow:hidden}
    .chart{padding:12px 14px 8px;min-height:245px}
    .chart svg{display:block;width:100%;height:auto;overflow:visible}
    .chart-grid{stroke:#edf1ec;stroke-width:1}
    .chart-label{fill:#89968d;font-size:10px;font-family:inherit}
    .chart-area{fill:url(#revenueFill);opacity:.75}
    .chart-line{fill:none;stroke:#31844c;stroke-width:3;stroke-linecap:round;stroke-linejoin:round}
    .chart-dot{fill:#fff;stroke:#31844c;stroke-width:2.5}
    .chart-bar{fill:url(#unitsFill);rx:5}
    .chart-key{display:flex;align-items:center;gap:6px;color:#728076;font-size:10px}
    .chart-key i{width:8px;height:8px;border-radius:50%;background:#388b4d}
    .units-key i{background:#97bd4f}
    .chart-empty{min-height:210px;display:grid;place-items:center;color:#96a097;font-size:12px;text-align:center;padding:24px}
    .analytics-lower{margin-bottom:18px}
    .top-product{display:grid;grid-template-columns:26px minmax(0,1fr) auto;gap:10px;align-items:center;padding:13px 18px;border-bottom:1px solid #eff2ef}
    .rank{width:24px;height:24px;border-radius:8px;display:grid;place-items:center;background:#eff6e9;color:#457346;font-size:10px;font-weight:750}
    .top-product-name{overflow:hidden;color:#35473a;font-size:11px;font-weight:650;text-overflow:ellipsis;white-space:nowrap}
    .top-product-meta{margin-top:3px;color:#98a299;font-size:9px}
    .top-product-revenue{color:#365c3d;font-size:10px;font-weight:700}
    @media(prefers-reduced-motion:reduce){.nav-link,.nav-link .nav-icon{transition:none}}
    @media(max-width:700px){.settings-layout{grid-template-columns:1fr;gap:10px}.settings-menu{display:flex;gap:6px;overflow-x:auto;padding:6px}.settings-tab{width:auto;white-space:nowrap}.account-actions{align-items:flex-start;flex-direction:column}}
    @media(max-width:900px){.analytics-grid{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <div id="app" class="app">
    <section id="auth" class="auth-wrap hidden">
      <div class="auth-card panel">
        <a class="brand" href="/" style="padding:0;margin-bottom:22px"><span class="brand-mark">▰</span><span class="brand-copy"><span class="brand-name">Stockroom</span><span class="brand-caption">Simple inventory for small shops</span></span></a>
        <h1 id="auth-title">Welcome back</h1><p id="auth-subtitle">Sign in to manage your inventory.</p>
        <form id="login"><div id="name-field" class="field hidden"><label for="name">Your name</label><input id="name" name="name" autocomplete="name"></div><div class="field"><label for="email">Email</label><input id="email" name="email" type="email" required autocomplete="email"></div><div class="field"><label for="password">Password</label><input id="password" name="password" type="password" required minlength="8" autocomplete="current-password"></div><p id="auth-error" class="auth-message"></p><div class="auth-actions"><button id="auth-submit" class="button">Sign in</button><button id="auth-toggle" class="button secondary" type="button">Create account</button></div></form>
      </div>
    </section>
    <div id="workspace" class="hidden">
      <div class="mobile-overlay" id="mobile-overlay"></div>
      <aside class="sidebar" id="sidebar">
        <a class="brand" href="#overview" data-page="overview"><span class="brand-mark">▰</span><span class="brand-copy"><span class="brand-name">Stockroom</span><span class="brand-caption">Inventory, made simple</span></span></a>
        <button id="collapse" class="collapse" type="button" aria-label="Collapse sidebar">‹</button>
        <p class="nav-caption">Workspace</p>
        <nav class="nav" aria-label="Main navigation">
          <button class="nav-link active" data-page="overview" title="Overview"><span class="nav-icon">▦</span><span class="nav-label">Overview</span></button>
          <button class="nav-link" data-page="products" title="Products"><span class="nav-icon">◇</span><span class="nav-label">Products</span><span id="product-count-nav" class="nav-count">0</span></button>
          <button class="nav-link" data-page="sales" title="Sales analytics"><span class="nav-icon">▥</span><span class="nav-label">Sales analytics</span></button>
          <button class="nav-link" data-page="low-stock" title="Low stock"><span class="nav-icon">△</span><span class="nav-label">Low stock</span><span id="low-count-nav" class="nav-count hidden">0</span></button>
          <button class="nav-link" data-page="account" title="Account settings"><span class="nav-icon">⚙</span><span class="nav-label">Account settings</span></button>
        </nav>
        <div class="sidebar-note"><strong>Your data stays here</strong>Your products are saved in this app’s local database under your account.</div>
      </aside>
      <main class="main">
        <header class="topbar"><div class="mobile-brand"><span class="brand-mark">▰</span>Stockroom</div><button id="mobile-menu" class="mobile-menu" type="button" aria-label="Open menu">☰</button><div id="breadcrumb" class="crumb">Workspace / <strong>Overview</strong></div><div class="top-actions"><div class="user-chip"><span id="avatar" class="avatar">U</span><span id="user-email">Account</span></div></div></header>
        <div class="content">
          <section id="page-overview" class="page">
            <div class="page-heading"><div><p class="eyebrow">Your workspace</p><h1>Overview</h1><p class="subheading">A quick look at the stock in your shop.</p></div><button class="button" data-go="products">＋ Add product</button></div>
            <div class="stats"><article class="panel stat"><span class="stat-icon">◇</span><span class="stat-label">Total products</span><strong id="stat-products" class="stat-value">0</strong><div class="stat-foot">Different items in your catalog</div></article><article class="panel stat"><span class="stat-icon">▤</span><span class="stat-label">Units in stock</span><strong id="stat-units" class="stat-value">0</strong><div class="stat-foot">Across all products</div></article><article class="panel stat"><span class="stat-icon">₱</span><span class="stat-label">Inventory value</span><strong id="stat-value" class="stat-value">₱0.00</strong><div class="stat-foot">Based on unit cost × quantity</div></article><article class="panel stat"><span class="stat-icon">△</span><span class="stat-label">Need attention</span><strong id="stat-low" class="stat-value">0</strong><div class="stat-foot">At or below reorder level</div></article></div>
            <div class="two-col"><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Recent products</h2><p class="panel-hint">Latest items in your inventory</p></div><button class="text-link" data-go="products">View products →</button></div><div id="overview-table" class="table-wrap"></div></section><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Stock alerts</h2><p class="panel-hint">Items at their reorder level</p></div><button class="text-link" data-go="low-stock">View all →</button></div><div id="overview-alerts"></div></section></div>
          </section>
          <section id="page-products" class="page hidden">
            <div class="page-heading"><div><p class="eyebrow">Inventory</p><h1>Products</h1><p class="subheading">Add and manage the items you keep in stock.</p></div><input id="search" class="search" type="search" placeholder="Search products…" aria-label="Search products"></div>
            <section class="panel form-panel"><div class="panel-head" style="padding:0 0 14px;margin-bottom:14px"><div><h2 class="panel-title">Add a product</h2><p class="panel-hint">Enter product details and current stock.</p></div></div><form id="add-product"><div class="form-grid"><div class="field"><label for="product-name">Product name</label><input id="product-name" name="name" required maxlength="120" placeholder="e.g. House Blend"></div><div class="field"><label for="product-sku">Product code</label><input id="product-sku" name="sku" required maxlength="80" placeholder="e.g. DRK-001"></div><div class="field"><label for="product-category">Category</label><input id="product-category" name="category" maxlength="80" placeholder="e.g. Drinks"></div><div class="field"><label for="product-quantity">Quantity</label><input id="product-quantity" name="quantity" type="number" min="0" required value="0"></div><div class="field"><label for="product-price">Unit cost (₱)</label><input id="product-price" name="price" type="number" min="0" step="0.01" required value="0"></div><div class="field"><label for="product-reorder">Reorder level</label><input id="product-reorder" name="reorder_level" type="number" min="0" required value="5"></div></div><div class="form-actions"><button class="button" type="submit">Add product</button></div><p id="message" class="notice"></p></form></section>
            <section class="panel"><div class="panel-head"><div><h2 class="panel-title">All products</h2><p id="product-summary" class="panel-hint">0 products</p></div><button id="refresh" class="button secondary" type="button">Refresh</button></div><div id="products-table" class="table-wrap"></div></section>
          </section>
          <section id="page-low-stock" class="page hidden">
            <div class="page-heading"><div><p class="eyebrow">Inventory alerts</p><h1>Low stock</h1><p class="subheading">Products at or below their reorder level.</p></div><button class="button secondary" data-go="products">Manage products</button></div>
            <section class="panel"><div class="panel-head"><div><h2 class="panel-title">Items to restock</h2><p id="low-summary" class="panel-hint">No alerts</p></div></div><div id="low-table" class="table-wrap"></div></section>
          </section>
          <section id="page-sales" class="page hidden">
            <div class="page-heading"><div><p class="eyebrow">Business performance</p><h1>Sales analytics</h1><p class="subheading">Track revenue and units sold from your recorded sales.</p></div><label class="field"><span class="hidden">Reporting period</span><select id="sales-period" class="search" aria-label="Reporting period"><option value="week">Last 7 days</option><option value="month">Last 30 days</option></select></label></div>
            <div class="stats"><article class="panel stat"><span class="stat-icon">₱</span><span class="stat-label">Sales revenue</span><strong id="sales-revenue" class="stat-value">₱0.00</strong><div id="sales-period-note" class="stat-foot">Last 7 days</div></article><article class="panel stat"><span class="stat-icon">▤</span><span class="stat-label">Units sold</span><strong id="sales-units" class="stat-value">0</strong><div class="stat-foot">Items sold in this period</div></article><article class="panel stat"><span class="stat-icon">↗</span><span class="stat-label">Transactions</span><strong id="sales-count" class="stat-value">0</strong><div class="stat-foot">Recorded sales</div></article><article class="panel stat"><span class="stat-icon">∅</span><span class="stat-label">Average sale</span><strong id="sales-average" class="stat-value">₱0.00</strong><div class="stat-foot">Revenue per transaction</div></article></div>
            <section class="panel form-panel"><div class="panel-head" style="padding:0 0 14px;margin-bottom:14px"><div><h2 class="panel-title">Record a sale</h2><p class="panel-hint">Enter the price the customer paid per item. Stock is reduced automatically.</p></div></div><form id="sale-form"><div class="form-grid"><div class="field"><label for="sale-product">Product</label><select id="sale-product" name="product_id" required><option value="">Choose a product</option></select></div><div class="field"><label for="sale-quantity">Quantity sold</label><input id="sale-quantity" name="quantity" type="number" min="1" required value="1"></div><div class="field"><label for="sale-price">Selling price per item (₱)</label><input id="sale-price" name="unit_price" type="number" min="0" step="0.01" required placeholder="e.g. 250.00"></div></div><div class="form-actions"><button id="record-sale" class="button" type="submit">Record sale</button></div><p id="sale-message" class="notice"></p></form></section>
            <div class="analytics-grid"><section class="panel chart-panel"><div class="panel-head"><div><h2 class="panel-title">Revenue trend</h2><p class="panel-hint">Sales revenue by day</p></div><span class="chart-key"><i></i> Revenue</span></div><div id="revenue-chart" class="chart"></div></section><section class="panel chart-panel"><div class="panel-head"><div><h2 class="panel-title">Units sold</h2><p class="panel-hint">Items sold by day</p></div><span class="chart-key units-key"><i></i> Units</span></div><div id="units-chart" class="chart"></div></section></div>
            <div class="two-col analytics-lower"><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Top products</h2><p class="panel-hint">Ranked by units sold in this period</p></div></div><div id="top-products"></div></section><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Recent sales</h2><p class="panel-hint">Latest recorded transactions</p></div></div><div id="recent-sales" class="table-wrap"></div></section></div>
          </section>
          <section id="page-account" class="page hidden">
            <div class="page-heading"><div><p class="eyebrow">Preferences</p><h1>Account settings</h1><p class="subheading">Manage your profile and account details.</p></div></div>
            <div class="settings-layout">
              <nav class="panel settings-menu" aria-label="Account settings"><button class="settings-tab active" data-settings-tab="profile" type="button">✎ <span>Edit profile</span></button><button class="settings-tab" data-settings-tab="photo" type="button">◎ <span>Profile picture</span></button></nav>
              <div>
                <section id="settings-profile" class="panel settings-body settings-panel"><div class="panel-head" style="padding:0 0 16px;margin-bottom:16px"><div><h2 class="panel-title">Edit profile</h2><p class="panel-hint">Update the name and email associated with your account.</p></div></div><form id="profile-form"><div class="form-grid" style="grid-template-columns:repeat(2,minmax(0,1fr))"><div class="field"><label for="profile-name">Your name</label><input id="profile-name" name="name" required maxlength="100" autocomplete="name"></div><div class="field"><label for="profile-email">Email address</label><input id="profile-email" name="email" type="email" required maxlength="255" autocomplete="email"></div></div><div class="form-actions"><button id="save-profile" class="button" type="submit">Save changes</button></div><p id="profile-message" class="notice"></p></form></section>
                <section id="settings-photo" class="panel settings-body settings-panel hidden"><div class="panel-head" style="padding:0 0 16px;margin-bottom:16px"><div><h2 class="panel-title">Profile picture</h2><p class="panel-hint">Add a photo to personalize your account.</p></div></div><form id="photo-form"><div style="display:flex;align-items:center;gap:17px;margin-bottom:18px"><div id="profile-photo-preview" class="avatar photo-preview">U</div><div><strong style="display:block;color:#384b3e;font-size:12px">Choose a profile photo</strong><p class="panel-hint">JPG, PNG, or WebP · up to 1 MB</p></div></div><div class="field"><label for="profile-photo">Upload image</label><input id="profile-photo" name="avatar" type="file" accept="image/jpeg,image/png,image/webp" required></div><div class="form-actions"><button id="save-photo" class="button" type="submit">Save picture</button></div><p id="photo-message" class="notice"></p></form></section>
              </div>
            </div>
            <section class="panel account-actions"><div><h2 class="panel-title">Sign out</h2><p class="panel-hint">Sign out of this Stockroom account on this device.</p></div><button id="signout" class="button signout" type="button">Sign out</button></section>
          </section>
        </div>
      </main>
    </div>
  </div>
  <script>
    const tokenKey='stockroom_token';
    const app=document.querySelector('#app');
    const auth=document.querySelector('#auth');
    const workspace=document.querySelector('#workspace');
    let token=localStorage.getItem(tokenKey);
    let products=[];
    let activePage='overview';
    let registering=false;
    let salesPeriod='week';

    async function request(path,options={}){
      const response=await fetch('/api'+path,{...options,headers:{Accept:'application/json','Content-Type':'application/json',...(token?{Authorization:`Bearer ${token}`}:{})}});
      const data=await response.json().catch(()=>({message:'The server returned an unexpected response.'}));
      if(response.status===401){signOutLocal();throw Error(data.message||'Please sign in again.');}
      if(!response.ok)throw Error(data.message||'Request failed.');
      return data;
    }
    function signOutLocal(){localStorage.removeItem(tokenKey);token=null;products=[];showState();}
    function paintAvatar(element,name,email,url){element.replaceChildren();if(url){const image=document.createElement('img');image.src=url;image.alt='';element.append(image);}else{element.textContent=(name||email||'U').slice(0,1).toUpperCase();}}
    function applyProfile(profile){const name=profile.name||'',email=profile.email||'';localStorage.setItem('stockroom_name',name);localStorage.setItem('stockroom_email',email);document.querySelector('#user-email').textContent=name||email||'Account';paintAvatar(document.querySelector('#avatar'),name,email,profile.avatar_url);paintAvatar(document.querySelector('#profile-photo-preview'),name,email,profile.avatar_url);}
    function showState(){auth.classList.toggle('hidden',!!token);workspace.classList.toggle('hidden',!token);if(token){document.querySelector('#user-email').textContent=localStorage.getItem('stockroom_name')||localStorage.getItem('stockroom_email')||'Account';paintAvatar(document.querySelector('#avatar'),localStorage.getItem('stockroom_name'),localStorage.getItem('stockroom_email'),null);loadProducts();loadProfile();}}
    function escapeHtml(value){return String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));}
    function status(product){if(Number(product.quantity)===0)return{label:'Out of stock',className:'out'};if(Number(product.quantity)<=Number(product.reorder_level))return{label:'Low stock',className:'low'};return{label:'In stock',className:'good'};}
    function tableMarkup(items){
      if(!items.length)return '<div class="empty">No products here yet.</div>';
      return `<table><thead><tr><th>Product</th><th>Code</th><th>Category</th><th>Quantity</th><th>Unit cost</th><th>Status</th><th></th></tr></thead><tbody>${items.map(product=>{const stock=status(product);return `<tr><td class="product-name">${escapeHtml(product.name)}</td><td class="sku">${escapeHtml(product.sku)}</td><td><span class="pill">${escapeHtml(product.category||'Uncategorized')}</span></td><td>${Number(product.quantity)}</td><td>₱${Number(product.price).toFixed(2)}</td><td><span class="status ${stock.className}">${stock.label}</span></td><td><button class="button danger" data-delete="${escapeHtml(product.id)}" type="button">Delete</button></td></tr>`;}).join('')}</tbody></table>`;
    }
    function renderProducts(){
      const low=products.filter(product=>Number(product.quantity)<=Number(product.reorder_level));
      const units=products.reduce((total,product)=>total+Number(product.quantity),0);
      const value=products.reduce((total,product)=>total+Number(product.quantity)*Number(product.price),0);
      document.querySelector('#stat-products').textContent=products.length;
      document.querySelector('#stat-units').textContent=units.toLocaleString();
      document.querySelector('#stat-value').textContent=`₱${value.toLocaleString('en-PH',{minimumFractionDigits:2,maximumFractionDigits:2})}`;
      document.querySelector('#stat-low').textContent=low.length;
      document.querySelector('#product-count-nav').textContent=products.length;
      document.querySelector('#low-count-nav').textContent=low.length;
      document.querySelector('#low-count-nav').classList.toggle('hidden',low.length===0);
      document.querySelector('#product-summary').textContent=`${products.length} product${products.length===1?'':'s'}`;
      document.querySelector('#overview-table').innerHTML=tableMarkup(products.slice(0,5));
      document.querySelector('#overview-alerts').innerHTML=tableMarkup(low.slice(0,4));
      document.querySelector('#products-table').innerHTML=tableMarkup(filteredProducts());
      document.querySelector('#low-table').innerHTML=tableMarkup(low);
      document.querySelector('#low-summary').textContent=low.length?`${low.length} item${low.length===1?'':'s'} need attention`:'No products need restocking';
      const selectedProduct=document.querySelector('#sale-product').value;
      document.querySelector('#sale-product').innerHTML='<option value="">Choose a product</option>'+products.map(product=>`<option value="${escapeHtml(product.id)}" ${Number(product.quantity)<1?'disabled':''}>${escapeHtml(product.name)} · ${Number(product.quantity)} in stock</option>`).join('');
      if(products.some(product=>String(product.id)===selectedProduct))document.querySelector('#sale-product').value=selectedProduct;
    }
    function lineChart(daily){
      if(!daily.some(day=>day.revenue>0))return '<div class="chart-empty">No sales recorded in this period yet.</div>';
      const width=700,height=230,left=56,right=18,top=18,bottom=40,innerW=width-left-right,innerH=height-top-bottom,max=Math.max(1,...daily.map(day=>day.revenue))*1.12;
      const points=daily.map((day,index)=>({x:left+(daily.length===1?innerW/2:index*innerW/(daily.length-1)),y:top+innerH-(day.revenue/max)*innerH,day}));
      const path=points.map((point,index)=>`${index?'L':'M'}${point.x.toFixed(1)},${point.y.toFixed(1)}`).join(' ');
      const area=`${path} L${points[points.length-1].x},${top+innerH} L${points[0].x},${top+innerH} Z`;
      const grid=Array.from({length:5},(_,index)=>{const y=top+innerH-index*innerH/4,value=max*index/4;return `<line class="chart-grid" x1="${left}" y1="${y}" x2="${width-right}" y2="${y}"/><text class="chart-label" x="${left-8}" y="${y+3}" text-anchor="end">₱${value>=1000?`${(value/1000).toFixed(1)}k`:Math.round(value)}</text>`;}).join('');
      const stride=daily.length>10?5:1;
      const labels=points.map((point,index)=>index%stride===0||index===points.length-1?`<text class="chart-label" x="${point.x}" y="${height-12}" text-anchor="middle">${escapeHtml(point.day.label)}</text>`:'').join('');
      const dots=points.map(point=>`<circle class="chart-dot" cx="${point.x}" cy="${point.y}" r="3.6"><title>${escapeHtml(point.day.label)}: ₱${Number(point.day.revenue).toFixed(2)}</title></circle>`).join('');
      return `<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="Daily sales revenue line chart"><defs><linearGradient id="revenueFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stop-color="#59ae65" stop-opacity=".32"/><stop offset="100%" stop-color="#d8edcf" stop-opacity=".04"/></linearGradient></defs>${grid}<path class="chart-area" d="${area}"/><path class="chart-line" d="${path}"/>${dots}${labels}</svg>`;
    }
    function unitsChart(daily){
      if(!daily.some(day=>day.units_sold>0))return '<div class="chart-empty">Your units sold will appear here after you record sales.</div>';
      const width=700,height=230,left=48,right=18,top=18,bottom=40,innerW=width-left-right,innerH=height-top-bottom,max=Math.max(1,...daily.map(day=>day.units_sold)),slot=innerW/daily.length,barW=Math.min(24,slot*.62);
      const grid=Array.from({length:5},(_,index)=>{const y=top+innerH-index*innerH/4,value=Math.round(max*index/4);return `<line class="chart-grid" x1="${left}" y1="${y}" x2="${width-right}" y2="${y}"/><text class="chart-label" x="${left-8}" y="${y+3}" text-anchor="end">${value}</text>`;}).join('');
      const stride=daily.length>10?5:1;
      const bars=daily.map((day,index)=>{const x=left+index*slot+(slot-barW)/2,bh=day.units_sold/max*innerH,y=top+innerH-bh;return `<rect class="chart-bar" x="${x}" y="${y}" width="${barW}" height="${Math.max(0,bh)}"><title>${escapeHtml(day.label)}: ${day.units_sold} units</title></rect>`;}).join('');
      const labels=daily.map((day,index)=>index%stride===0||index===daily.length-1?`<text class="chart-label" x="${left+index*slot+slot/2}" y="${height-12}" text-anchor="middle">${escapeHtml(day.label)}</text>`:'').join('');
      return `<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="Daily units sold bar chart"><defs><linearGradient id="unitsFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stop-color="#9bc451"/><stop offset="100%" stop-color="#d1e4a7"/></linearGradient></defs>${grid}${bars}${labels}</svg>`;
    }
    function renderAnalytics(data){
      const money=value=>`₱${Number(value).toLocaleString('en-PH',{minimumFractionDigits:2,maximumFractionDigits:2})}`;
      document.querySelector('#sales-revenue').textContent=money(data.totals.revenue);
      document.querySelector('#sales-units').textContent=Number(data.totals.units_sold).toLocaleString();
      document.querySelector('#sales-count').textContent=Number(data.totals.sales_count).toLocaleString();
      document.querySelector('#sales-average').textContent=money(data.totals.sales_count?data.totals.revenue/data.totals.sales_count:0);
      document.querySelector('#sales-period-note').textContent=salesPeriod==='week'?'Last 7 days':'Last 30 days';
      document.querySelector('#revenue-chart').innerHTML=lineChart(data.daily);
      document.querySelector('#units-chart').innerHTML=unitsChart(data.daily);
      const maxUnits=Math.max(1,...data.top_products.map(product=>Number(product.units_sold)));
      document.querySelector('#top-products').innerHTML=data.top_products.length?data.top_products.map((product,index)=>`<div class="top-product"><span class="rank">${index+1}</span><div><div class="top-product-name">${escapeHtml(product.name)}</div><div class="top-product-meta">${Number(product.units_sold)} units · ${Math.round(Number(product.units_sold)/maxUnits*100)}% of top item</div></div><span class="top-product-revenue">${money(product.revenue)}</span></div>`).join(''):'<div class="empty">Record sales to see your best-selling products.</div>';
      document.querySelector('#recent-sales').innerHTML=data.recent.length?`<table><thead><tr><th>Product</th><th>Qty</th><th>Sale total</th><th>When</th></tr></thead><tbody>${data.recent.map(sale=>`<tr><td class="product-name">${escapeHtml(sale.product_name)}</td><td>${sale.quantity}</td><td>${money(sale.total)}</td><td>${new Date(sale.created_at).toLocaleDateString('en-PH',{month:'short',day:'numeric'})}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">No sales recorded in this period yet.</div>';
    }
    async function loadAnalytics(){try{const data=await request(`/sales/analytics?period=${salesPeriod}`);renderAnalytics(data);}catch(error){document.querySelector('#sale-message').textContent=error.message;}}
    function filteredProducts(){const query=document.querySelector('#search').value.trim().toLowerCase();return products.filter(product=>`${product.name} ${product.sku} ${product.category||''}`.toLowerCase().includes(query));}
    async function loadProducts(){try{products=await request('/products');renderProducts();}catch(error){if(token)document.querySelector('#message').textContent=error.message;}}
    async function loadProfile(){try{const profile=await request('/profile');document.querySelector('#profile-name').value=profile.name||'';document.querySelector('#profile-email').value=profile.email||'';applyProfile(profile);document.querySelector('#profile-message').textContent='';}catch(error){document.querySelector('#profile-message').textContent=error.message;}}
    function navigate(page){activePage=page;document.querySelectorAll('.page').forEach(section=>section.classList.toggle('hidden',section.id!==`page-${page}`));document.querySelectorAll('.nav-link').forEach(link=>link.classList.toggle('active',link.dataset.page===page));const labels={overview:'Overview',products:'Products',sales:'Sales analytics','low-stock':'Low stock',account:'Account settings'};document.querySelector('#breadcrumb').innerHTML=`Workspace / <strong>${labels[page]||'Overview'}</strong>`;app.classList.remove('mobile-open');history.replaceState(null,'',`#${page}`);if(page==='account')loadProfile();if(page==='sales')loadAnalytics();}

    document.querySelector('#auth-toggle').addEventListener('click',()=>{registering=!registering;document.querySelector('#name-field').classList.toggle('hidden',!registering);document.querySelector('#name').required=registering;document.querySelector('#auth-title').textContent=registering?'Create your account':'Welcome back';document.querySelector('#auth-subtitle').textContent=registering?'Start organizing your inventory.':'Sign in to manage your inventory.';document.querySelector('#auth-submit').textContent=registering?'Create account':'Sign in';document.querySelector('#auth-toggle').textContent=registering?'Back to sign in':'Create account';document.querySelector('#password').autocomplete=registering?'new-password':'current-password';});
    document.querySelector('#login').addEventListener('submit',async event=>{event.preventDefault();const form=new FormData(event.currentTarget);const payload=Object.fromEntries(form);try{const data=await request(registering?'/register':'/login',{method:'POST',body:JSON.stringify(payload)});token=data.token;localStorage.setItem(tokenKey,token);localStorage.setItem('stockroom_email',payload.email);localStorage.setItem('stockroom_name',data.user?.name||payload.name||'');document.querySelector('#auth-error').textContent='';showState();}catch(error){document.querySelector('#auth-error').textContent=error.message;}});
    document.querySelector('#add-product').addEventListener('submit',async event=>{event.preventDefault();const message=document.querySelector('#message');message.textContent='';const data=Object.fromEntries(new FormData(event.currentTarget));for(const key of ['quantity','reorder_level'])data[key]=Number(data[key]);data.price=Number(data.price);try{await request('/products',{method:'POST',body:JSON.stringify(data)});event.currentTarget.reset();document.querySelector('#product-quantity').value=0;document.querySelector('#product-price').value=0;document.querySelector('#product-reorder').value=5;message.textContent='Product added.';await loadProducts();}catch(error){message.textContent=error.message;}});
    document.querySelector('#sale-form').addEventListener('submit',async event=>{event.preventDefault();const button=document.querySelector('#record-sale'),message=document.querySelector('#sale-message'),data=Object.fromEntries(new FormData(event.currentTarget));data.product_id=Number(data.product_id);data.quantity=Number(data.quantity);data.unit_price=Number(data.unit_price);button.disabled=true;message.textContent='';message.style.color='';try{const result=await request('/sales',{method:'POST',body:JSON.stringify(data)});message.style.color='#287746';message.textContent=`Sale recorded. ${result.remaining_quantity} unit${result.remaining_quantity===1?'':'s'} left in stock.`;document.querySelector('#sale-price').value='';document.querySelector('#sale-quantity').value=1;await loadProducts();await loadAnalytics();}catch(error){message.textContent=error.message;}finally{button.disabled=false;}});
    document.querySelector('#sales-period').addEventListener('change',event=>{salesPeriod=event.target.value;loadAnalytics();});
    document.querySelector('#sale-product').addEventListener('change',event=>{const product=products.find(item=>String(item.id)===event.target.value);const quantity=document.querySelector('#sale-quantity');quantity.max=product?product.quantity:'';if(product&&Number(quantity.value)>product.quantity)quantity.value=Math.max(1,product.quantity);});
    document.querySelector('#products-table').addEventListener('click',async event=>{const id=event.target.dataset.delete;if(!id)return;if(!confirm('Delete this product from your inventory?'))return;try{await request(`/products/${id}`,{method:'DELETE'});await loadProducts();}catch(error){document.querySelector('#message').textContent=error.message;}});
    document.querySelector('#overview-table').addEventListener('click',event=>{const id=event.target.dataset.delete;if(id)document.querySelector('#products-table').querySelector(`[data-delete="${CSS.escape(id)}"]`)?.click();});
    document.querySelector('#low-table').addEventListener('click',event=>{const id=event.target.dataset.delete;if(id)document.querySelector('#products-table').querySelector(`[data-delete="${CSS.escape(id)}"]`)?.click();});
    document.querySelectorAll('[data-page]').forEach(button=>button.addEventListener('click',()=>navigate(button.dataset.page)));
    document.querySelectorAll('[data-go]').forEach(button=>button.addEventListener('click',()=>navigate(button.dataset.go)));
    document.querySelector('#search').addEventListener('input',()=>{document.querySelector('#products-table').innerHTML=tableMarkup(filteredProducts());});
    document.querySelector('#refresh').addEventListener('click',loadProducts);
    document.querySelector('#profile-form').addEventListener('submit',async event=>{event.preventDefault();const button=document.querySelector('#save-profile'),message=document.querySelector('#profile-message');button.disabled=true;message.textContent='';try{const profile=await request('/profile',{method:'PUT',body:JSON.stringify(Object.fromEntries(new FormData(event.currentTarget)))});applyProfile(profile);message.style.color='#287746';message.textContent='Profile details saved.';}catch(error){message.style.color='';message.textContent=error.message;}finally{button.disabled=false;}});
    document.querySelectorAll('[data-settings-tab]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-settings-tab]').forEach(tab=>tab.classList.toggle('active',tab===button));document.querySelectorAll('.settings-panel').forEach(panel=>panel.classList.toggle('hidden',panel.id!==`settings-${button.dataset.settingsTab}`));}));
    document.querySelector('#profile-photo').addEventListener('change',event=>{const file=event.target.files?.[0];if(!file)return;if(file.size>1024*1024){document.querySelector('#photo-message').textContent='Choose an image smaller than 1 MB.';event.target.value='';return;}const reader=new FileReader();reader.onload=()=>{paintAvatar(document.querySelector('#profile-photo-preview'),'','',reader.result);};reader.readAsDataURL(file);document.querySelector('#photo-message').textContent='';});
    document.querySelector('#photo-form').addEventListener('submit',async event=>{event.preventDefault();const button=document.querySelector('#save-photo'),message=document.querySelector('#photo-message');button.disabled=true;message.textContent='';try{const response=await fetch('/api/profile/avatar',{method:'POST',headers:{Accept:'application/json',Authorization:`Bearer ${token}`},body:new FormData(event.currentTarget)});const profile=await response.json().catch(()=>({message:'The server returned an unexpected response.'}));if(response.status===401){signOutLocal();throw Error('Please sign in again.');}if(!response.ok)throw Error(profile.message||'Could not save the profile picture.');applyProfile(profile);message.style.color='#287746';message.textContent='Profile picture saved.';event.currentTarget.reset();}catch(error){message.style.color='';message.textContent=error.message;}finally{button.disabled=false;}});
    document.querySelector('#collapse').addEventListener('click',()=>{app.classList.toggle('collapsed');document.querySelector('#collapse').textContent=app.classList.contains('collapsed')?'›':'‹';});
    document.querySelector('#mobile-menu').addEventListener('click',()=>app.classList.toggle('mobile-open'));
    document.querySelector('#mobile-overlay').addEventListener('click',()=>app.classList.remove('mobile-open'));
    document.querySelector('#signout').addEventListener('click',async()=>{try{await request('/logout',{method:'POST'});}catch{}localStorage.removeItem('stockroom_email');localStorage.removeItem('stockroom_name');signOutLocal();});
    const startingPage=location.hash.slice(1);if(['overview','products','sales','low-stock','account'].includes(startingPage))navigate(startingPage);showState();
  </script>
</body>
</html>
